    "en": "2/4/1 tis Necessity is indeed the mother of invention. When areas in and around Leh began to experience water shortages, life didn’t grind to a halt. Why ? Because a retired civil engineer in the Jammu and Kashmir Government came up with the idea of artificial glaciers. Ladakh, a cold desert at an altitude of 3,000 — 3,500 meters above sea level, has a low average annual rainfall rate of 50 mm. Glaciers have always been the only source of water. Agriculture is completely dependent on glacier melt, unlike the rest of river/monsoon-fed India. But over the years, with increasing effects of climate change, rainfall and snowfall patterns have been changing, resulting in severe shortage and drought situations. Given the extreme winter conditions, the window for farming is usually limited to one harvest season. It is located between the natural glacier above and the village below. The one closer to the village and lowest in altitude melts first, providing water during April—May, the crucial sowing season. Further, layers of ice above melt with the increasing temperature, thus ensuring continuous supply to the fields. Therefore, farmers have been able to manage two crops instead of one. It",
