    "en": "Read the given extract and answer any one of the following questions given below : (a) It was a new bus, its outside painted a gleaming white with some green stripes along the sides. Inside, the overhead bars shone like silver. Directly in front of Valli, above the windshield, there was a beautiful clock. The seats were soft and luxurious. Valli devoured everything with her eyes. But when she started to look outside, she found her view cut off by a canvas blind that covered the lower part of her window. So she stood up on the seat and peered over the blind. (Madam Rides a Bus) { } (i) The effect on Valli as she describes the bus reveals that she is _________. Choose the most suitable option. (A) awed (B) scared (C) disgusted (D) repulsed (ii) How does the author’s use of descriptive language enhance the narrative technique in the passage ? (iii) Fill in the blank with the correct word from the bracket. The use of the word ‘devoured’ adds to a sense of _______ (fascination / hunger) in the extract. (iv) Which action of Valli shows that she did not want to miss out on any part of the experience ? OR (b) Mme Loisel was a great success. She was the prettiest of all – elegant, gracious,",
    "hi": "",
    "ans": "",
    "fig": null,
