    "en": "Read the given extract and answer any one of the following questions given below : (a) Mme Loisel was a great success. She was the prettiest of all – elegant, gracious, smiling, and full of joy. All the men noticed her, asked her name and wanted to be presented. She danced with enthusiasm, intoxicated with pleasure, thinking of nothing but all this admiration, this victory so complete and sweet to her heart. (The Necklace) (i) How is “success” perceived by Matilda ? (ii) Fill in the blank with the correct word from the bracket. ‘All the men noticed her, asked her name and wanted to be presented’ indicates that the men wanted to be formally _______ (introduced / withholden) to her. (iii) Which of the following best describe Matilda’s state of mind in the context ? (A) overwhelmed (B) anxious (C) confused (D) sad (iv) Explain the phrase “this victory so complete and sweet to her heart”. OR (b) It was a new bus, its outside painted a gleaming white with some green stripes along the sides. Inside, the overhead bars shone like silver. Directly in front of Valli, above the windshield, there was a beautiful clock. The seats were soft and luxurious. Valli devoured everything with her eyes.",
