    "en": "Read the given extracts and answer the questions for any ONE of the two given. (a) He senses first responsibility In a world of possessions. People will take Balls, balls will be lost always, little boy. And no one buys a ball back. Money is external He is learning, well behind his desperate eyes, The epistemology of loss, how to stand up Knowing what every man must one day know And most know many days, how to stand up. (The Ball Poem) (i) Comment on the portrayal of the character of the boy in the given extract. (ii) Complete the following suitably : “Money is external” implies that the boy _______ (A) values material possessions. (B) learns the money cannot restore what is lost. (C) believes money is the solution to all problems. (D) is indifferent to material wealth. (iii) What does the poet mean by the phrase, ‘epistemology of loss’ ? (iv) What kind of atmosphere is created through these lines ? Select the correct option.",
