    "en": "Read the text given below : 10 Marks (1) Held every year on 21 May, UNESCO leads the celebration of World Day for Cultural Diversity for Dialogue and Development highlighting not only the richness of the world’s cultures, but also the essential role of intercultural dialogue for achieving peace and sustainable development. (2) A recent international emergency has proved the intrinsic value of the cultural and creative sector at generating social cohesion, educational resource or personal well-being in times of crisis. It has also underscored the sector’s potential to generate economic growth, something which is too often underestimated. (3) With the adoption in September 2015 of the 2030 Agenda for Sustainable Development by the United Nations, and the resolution on Culture and Sustainable Development adopted by the UN General Assembly in December 2015, the message of the World Day for Cultural Diversity for Dialogue and Development is more important than ever. The 17 Sustainable Development Goals (SDGs) can best be achieved by drawing upon the creative potential of the world’s diverse cultures and engaging in continuous dialogue to ensure that all members of society benefit from s",
