    "d": 1,
    "en": "Read the extract given below: 10 Marks (1) The National Education Policy 2020 proposes the revision and revamping of all aspects of education, including the educational structure, regulations and governance, to create a new system which is aligned with the aspirational goals of 21st century students. According to the policy, by 2025, at least 50% of learners through the school and higher education system shall have exposure to skill education, for which a clear action plan with targets and timelines are to be developed. (2) The policy aims to overcome the social status hierarchy associated with skill education and integration of skill education into mainstream education in all educational institutions in a phased manner. Beginning with skill exposure at early ages in middle and secondary school, quality skill education will be integrated smoothly into school and higher education. 2/1/1 / 31 4 AW (3) Every child will learn at least one skill and is exposed to several more. This would lead to emphasizing the dignity of labour and importance of various vocations involving Indian arts and artisanship. (4) The development of skill capacities will go hand-in-hand with the development of",
