    "d": 1,
    "en": "(B) 2/1/1 /31 differences and created a system of racial domination against the dark-skinned people of their own land. The structure they created formed the basis of one of the harshest, most inhumane societies the world has ever known. Now, in the last decade of the twentienth century, and my own eighth decade as a man, that system has been overturned forever and replaced by one that recognised the rights and freedoms of all peoples, regardless of the colour of their skin. (i) Explain the feelings of the narrator when he said ; “I was overwhelmed with a sense of history.” (ii) The system of racial domination has been replaced by a system that : (A) confirms the education of the Blacks. (B) recognises the rights and freedoms of all people. (C) recollects the bitter experiences. (D) focuses on the personality development. (iii) Comment on the kind of society apartheid had created ? (iv) Which phrase would correctly substitute ‘patched up’ in the given sentence from the extract : “the white skinned people of South Africa patched up their differences...” OR I started right away at the Montessori Nursery School. I stayed there until I was six, at which time I started in the first form.",
