    "en": "Read the following text : 10M (1) Fossil fuels (oil, coal, and natural gas) are our most traditional sources for power generation. The energy that’s produced from any source other than fossil fuels is termed as alternative energy. Between the two sources, using alternative energy has a lower environmental impact. (2) We now know that alternative energy sources are the sources we use to supplement or even replace traditional energy sources used for power generation. You could almost say the same thing about renewable energy sources. But there is one subtle difference between the two. All renewable energy sources fall under the category of alternative energy sources, but it doesn’t work the other way around. (3) That’s because renewable energy sources are derived from naturally replenished sources or processes of Earth, such as the sun, wind, and water. We refer to these resources as renewable or sustainable since, unlike fossil fuels, this naturally occurring continual renewal makes them inexhaustible. However, alternative energy sources are exhaustible, and therefore not renewable. That’s the difference ! 2/3/1/22 2 TA NAN AADAAAAAAAAAAAAAAAG (5) (6) (7) (8) 2/3/1/22 The equipment",
