    "en": "Read the following passage and answer the questions that follow : (1) There is no denying that the army is mainly responsible for the defence of the nation. It is also called upon to maintain law and order in times of severe crisis. However, we must not forget that the need to maintain law and order also arises in normal times. It is in these times that we need another force — the police — that compels citizens to obey the law and to act with due regard to the rights of others. The force also protects the lives and the properties of law-abiding citizens. (2) Laws are essentially made to secure the personal safety of the citizens of a country. They aim to prevent different types of crimes that pose a threat to the security of people and safety of their property, such as larceny, murder and numerous other illegal practices involving violence of any type. Besides ensuring security of the property of the citizens against theft and damage, laws also try to protect the rights of communities and castes to carry out their customs and ceremonies, so long as they do not conflict with the rights of others. (3) It is important to note that the enforcement of laws multiplies the duties and resp",
