    "en": "Read the passage given below : 10M (1) People have worn hats throughout history for practical reasons like protection from the elements, as well as social and cultural ones, such as displaying status, expressing individuality, and for religious or ceremonial purposes. Early headwear was for survival against the weather and injury, while later, hats became symbols of wealth, profession, and social rank. Today, reasons for wearing hats often include fashion, personal expression, and safety or comfort, with many of the old social pressures for wearing hats having faded. (2) Ido not remember how I came to like wearing a hat. Friends view it as an odd habit of mine, since few people wear hats today. I think my fondness for hats comes down to the desire to announce what type of person I am. Telling the world what kind of person resides below its brim is one of the principal jobs of any hat worth its name. 2/8/1 * Page 2of 16 * (3) Even if we are not supposed to judge a book by its cover, we very often judge a person by his or her hat. In a narrow sense, a top hat indicates to all that you are a magician, just as a mortarboard and tassel tells the world you just graduated. More generally",
