    "en": "Read the following passage carefully : (1) Saffron is a spice that’s long been revered across the globe, captivating hearts and palates with its deep-red hue and complex flavour. It is one of the most prized spices that you can find on this planet. Just like gold is among the most valuable metals in the world, saffron means the same in the world of spices. Also known as ‘kesar’ in Hindi, it has a rich history and is often called an ancient spice. Saffron is being used since ages in various foods made for the royals and the elite as it contains medicinal properties. (2) Originating from the delicate stigma of the saffron crocus flower, it transforms the ordinary into the extraordinary, infusing dishes with a subtle, earthy sweetness that adds a special taste to the palate. Saffron has a strong exotic aroma and a unique flavour and is used to colour and flavour many Mediterranean and Asian dishes, particularly rice, fish and English, Scandinavian, and Balkan breads. (3) Saffron forms the backbone of several iconic dishes from around the world, such as the Spanish rice, seafood dish Paella, the French stew Bouillabaisse, Italian rice dish Risotto Milanese, the Indian ice cream Kesar K",
