    "en": "Read the following extracts and answer the questions for any one of the given two, (a) or (b) : (a) He felt certain that his wings would never support him; so he bent his head and ran away back to the little hole under the ledge where he slept at night. Even when each of his brothers and his little sister, whose wings were far shorter than his own, ran to the brink, flapped their wings, and flew away, he failed to muster up courage to take that plunge which appeared to him so desperate. His father and mother had come around calling to him shrilly, upbraiding him, threatening to let him starve on his ledge unless he flew away. But for the life of him he could not move. (Two Stories about Flying – His First Flight) (i) State any one inference about the parents of the baby seagull from the given statement. “His father and mother had come around calling to him shrilly, upbraiding him, threatening to let him starve on his ledge unless he flew away.” (ii) Where did the little seagull sleep at night ? (iii) Which factors contributed to the young seagull’s reluctance to fly despite the encouragement and threats from his parents ? Elaborate in about 40 words, with reference to the extract.",
