    "en": "Read the following passage carefully : (1) Silk is a natural protein fibre, some forms of which can be woven into textiles. Silk has a long history in India. It is known as Resham in eastern and northern India, and Pattu in the southern parts of India. India is the second largest producer of silk in the world after China. (2) Silk is renowned for its luxurious qualities with a natural soft and smooth texture that feels comfortable on the skin. One of its unique qualities is to absorb and release moisture, regulating the body temperature, and keeping the wearer cool and dry. (3) Silk is one of the strongest natural fibres, but it loses up to 20% of its strength when wet. Its elasticity is moderate to poor: if elongated even a small amount, it remains stretched. It can be weakened if exposed to too much sunlight. It may also be attacked by insects, especially if left dirty. (4) The process of silk production is known as sericulture. Silk is produced by several insects; but, generally, only the silk of moth caterpillars has been used for textile manufacturing. To produce 1 kg of silk, 104 kg of mulberry leaves must be eaten by 3000 silkworms. (5) So what makes silk so costly ? Firstly",
